insert into control (control_id, family, title, statement, is_enhancement, parent_control_id, is_withdrawn, methods, catalog_version) values ('sa-10.2', 'sa', 'Alternative Configuration Management Processes', 'Provide an alternate configuration management process using organizational personnel in the absence of a dedicated developer configuration management team.', true, 'sa-10', false, '{examine,interview,test}'::assessment_method[], '5.2.0');
insert into control (control_id, family, title, statement, is_enhancement, parent_control_id, is_withdrawn, methods, catalog_version) values ('sa-10.3', 'sa', 'Hardware Integrity Verification', 'Require the developer of the system, system component, or system service to enable integrity verification of hardware components.', true, 'sa-10', false, '{examine,interview,test}'::assessment_method[], '5.2.0');
