insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-2.7_obj.b', 'ac-2.7', 'ac-2.7_obj', 'privileged role or attribute assignments are monitored;', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-2.7_obj.c', 'ac-2.7', 'ac-2.7_obj', 'changes to roles or attributes are monitored;', true, 1, 4);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-2.7_obj.d', 'ac-2.7', 'ac-2.7_obj', 'access is revoked when privileged role or attribute assignments are no longer appropriate.', true, 1, 5);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-2.8_obj', 'ac-2.8', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-2.8_obj-1', 'ac-2.8', 'ac-2.8_obj', '{{ insert: param, ac-02.08_odp }} are created dynamically;', true, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-2.8_obj-2', 'ac-2.8', 'ac-2.8_obj', '{{ insert: param, ac-02.08_odp }} are activated dynamically;', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-2.8_obj-3', 'ac-2.8', 'ac-2.8_obj', '{{ insert: param, ac-02.08_odp }} are managed dynamically;', true, 1, 4);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-2.8_obj-4', 'ac-2.8', 'ac-2.8_obj', '{{ insert: param, ac-02.08_odp }} are deactivated dynamically.', true, 1, 5);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-2.9_obj', 'ac-2.9', null, 'the use of shared and group accounts is only permitted if {{ insert: param, ac-02.09_odp }} are met.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-20_obj', 'ac-20', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-20_obj.a', 'ac-20', 'ac-20_obj', null, false, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-20_obj.b', 'ac-20', 'ac-20_obj', 'the use of {{ insert: param, ac-20_odp.04 }} is prohibited (if applicable).', true, 1, 5);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-20_obj.a.1', 'ac-20', 'ac-20_obj.a', '{{ insert: param, ac-20_odp.01 }} is/are consistent with the trust relationships established with other organizations owning, operating, and/or maintaining external systems, allowing authorized individuals to access the system from external systems (if applicable);', true, 2, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-20_obj.a.2', 'ac-20', 'ac-20_obj.a', '{{ insert: param, ac-20_odp.01 }} is/are consistent with the trust relationships established with other organizations owning, operating, and/or maintaining external systems, allowing authorized individuals to process, store, or transmit organization-controlled information using external systems (if applicable);', true, 2, 4);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-20.1_obj', 'ac-20.1', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-20.1_obj.a', 'ac-20.1', 'ac-20.1_obj', 'authorized individuals are permitted to use an external system to access the system or to process, store, or transmit organization-controlled information only after verification of the implementation of controls on the external system as specified in the organization’s security and privacy policies and security and privacy plans (if applicable);', true, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-20.1_obj.b', 'ac-20.1', 'ac-20.1_obj', 'authorized individuals are permitted to use an external system to access the system or to process, store, or transmit organization-controlled information only after retention of approved system connection or processing agreements with the organizational entity hosting the external system (if applicable).', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-20.2_obj', 'ac-20.2', null, 'the use of organization-controlled portable storage devices by authorized individuals is restricted on external systems using {{ insert: param, ac-20.02_odp }}.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-20.3_obj', 'ac-20.3', null, 'the use of non-organizationally owned systems or system components to process, store, or transmit organizational information is restricted using {{ insert: param, ac-20.03_odp }}.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-20.4_obj', 'ac-20.4', null, 'the use of {{ insert: param, ac-20.04_odp }} is prohibited in external systems.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-20.5_obj', 'ac-20.5', null, 'the use of organization-controlled portable storage devices by authorized individuals is prohibited on external systems.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-21_obj', 'ac-21', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-21_obj.a', 'ac-21', 'ac-21_obj', 'authorized users are enabled to determine whether access authorizations assigned to a sharing partner match the information’s access and use restrictions for {{ insert: param, ac-21_odp.01 }};', true, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-21_obj.b', 'ac-21', 'ac-21_obj', '{{ insert: param, ac-21_odp.02 }} are employed to assist users in making information-sharing and collaboration decisions.', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-21.1_obj', 'ac-21.1', null, '{{ insert: param, ac-21.01_odp }} are employed to enforce information-sharing decisions by authorized users based on access authorizations of sharing partners and access restrictions on information to be shared.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-21.2_obj', 'ac-21.2', null, 'information search and retrieval services that enforce {{ insert: param, ac-21.02_odp }} are implemented.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-22_obj', 'ac-22', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-22_obj.a', 'ac-22', 'ac-22_obj', 'designated individuals are authorized to make information publicly accessible;', true, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-22_obj.b', 'ac-22', 'ac-22_obj', 'authorized individuals are trained to ensure that publicly accessible information does not contain non-public information;', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-22_obj.c', 'ac-22', 'ac-22_obj', 'the proposed content of information is reviewed prior to posting onto the publicly accessible system to ensure that non-public information is not included;', true, 1, 4);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-22_obj.d', 'ac-22', 'ac-22_obj', null, false, 1, 5);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-22_obj.d-1', 'ac-22', 'ac-22_obj.d', 'the content on the publicly accessible system is reviewed for non-public information {{ insert: param, ac-22_odp }};', true, 2, 6);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-22_obj.d-2', 'ac-22', 'ac-22_obj.d', 'non-public information is removed from the publicly accessible system, if discovered.', true, 2, 7);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-23_obj', 'ac-23', null, '{{ insert: param, ac-23_odp.01 }} are employed for {{ insert: param, ac-23_odp.02 }} to detect and protect against unauthorized data mining.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-24_obj', 'ac-24', null, '{{ insert: param, ac-24_odp.01 }} are taken to ensure that {{ insert: param, ac-24_odp.02 }} are applied to each access request prior to access enforcement.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-24.1_obj', 'ac-24.1', null, '{{ insert: param, ac-24.01_odp.01 }} is transmitted using {{ insert: param, ac-24.01_odp.02 }} to {{ insert: param, ac-24.01_odp.03 }} that enforce access control decisions.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-24.2_obj', 'ac-24.2', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-24.2_obj-1', 'ac-24.2', 'ac-24.2_obj', 'access control decisions are enforced based on {{ insert: param, ac-24.02_odp.01 }} that do not include the identity of the user or process acting on behalf of the user (if selected);', true, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-24.2_obj-2', 'ac-24.2', 'ac-24.2_obj', 'access control decisions are enforced based on {{ insert: param, ac-24.02_odp.02 }} that do not include the identity of the user or process acting on behalf of the user (if selected).', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-25_obj', 'ac-25', null, 'a reference monitor is implemented for {{ insert: param, ac-25_odp }} that is tamper-proof, always invoked, and small enough to be subject to analysis and testing, the completeness of which can be assured.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3_obj', 'ac-3', null, 'approved authorizations for logical access to information and system resources are enforced in accordance with applicable access control policies.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.10_obj', 'ac-3.10', null, 'an audited override of automated access control mechanisms is employed under {{ insert: param, ac-03.10_odp.01 }} by {{ insert: param, ac-03.10_odp.02 }}.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.11_obj', 'ac-3.11', null, 'access to data repositories containing {{ insert: param, ac-03.11_odp }} is restricted.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.12_obj', 'ac-3.12', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.12_obj.a', 'ac-3.12', 'ac-3.12_obj', 'as part of the installation process, applications are required to assert the access needed to the following system applications and functions: {{ insert: param, ac-03.12_odp }};', true, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.12_obj.b', 'ac-3.12', 'ac-3.12_obj', 'an enforcement mechanism to prevent unauthorized access is provided; ', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.12_obj.c', 'ac-3.12', 'ac-3.12_obj', 'access changes after initial installation of the application are approved.', true, 1, 4);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.13_obj', 'ac-3.13', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.13_obj-1', 'ac-3.13', 'ac-3.13_obj', 'the attribute-based access control policy is enforced over defined subjects;', true, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.13_obj-2', 'ac-3.13', 'ac-3.13_obj', 'the attribute-based access control policy is enforced over defined objects;', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.13_obj-3', 'ac-3.13', 'ac-3.13_obj', 'access is controlled based on {{ insert: param, ac-03.13_odp }}.', true, 1, 4);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.14_obj', 'ac-3.14', null, '{{ insert: param, ac-03.14_odp.01 }} are provided to enable individuals to have access to {{ insert: param, ac-03.14_odp.02 }} of their personally identifiable information.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.15_obj', 'ac-3.15', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.15_obj.a', 'ac-3.15', 'ac-3.15_obj', null, false, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.15_obj.b', 'ac-3.15', 'ac-3.15_obj', null, false, 1, 5);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.15_obj.a-1', 'ac-3.15', 'ac-3.15_obj.a', '{{ insert: param, ac-03.15_odp.01 }} is enforced over the set of covered subjects specified in the policy;', true, 2, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.15_obj.a-2', 'ac-3.15', 'ac-3.15_obj.a', '{{ insert: param, ac-03.15_odp.02 }} is enforced over the set of covered objects specified in the policy;', true, 2, 4);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.15_obj.b-1', 'ac-3.15', 'ac-3.15_obj.b', '{{ insert: param, ac-03.15_odp.03 }} is enforced over the set of covered subjects specified in the policy;', true, 2, 6);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.15_obj.b-2', 'ac-3.15', 'ac-3.15_obj.b', '{{ insert: param, ac-03.15_odp.04 }} is enforced over the set of covered objects specified in the policy.', true, 2, 7);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.2_obj', 'ac-3.2', null, 'dual authorization is enforced for {{ insert: param, ac-03.02_odp }}.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.3_obj', 'ac-3.3', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.3_obj-1', 'ac-3.3', 'ac-3.3_obj', '{{ insert: param, ac-03.03_odp.01 }} is enforced over the set of covered subjects specified in the policy;', true, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.3_obj-2', 'ac-3.3', 'ac-3.3_obj', '{{ insert: param, ac-03.03_odp.02 }} is enforced over the set of covered objects specified in the policy;', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.3_obj.a', 'ac-3.3', 'ac-3.3_obj', null, false, 1, 4);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.3_obj.b', 'ac-3.3', 'ac-3.3_obj', null, false, 1, 7);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.3_obj.c', 'ac-3.3', 'ac-3.3_obj', '{{ insert: param, ac-03.03_odp.01 }} and {{ insert: param, ac-03.03_odp.02 }} specifying that {{ insert: param, ac-03.03_odp.03 }} may explicitly be granted {{ insert: param, ac-03.03_odp.04 }} such that they are not limited by any defined subset (or all) of the above constraints are enforced.', true, 1, 13);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.3_obj.a-1', 'ac-3.3', 'ac-3.3_obj.a', '{{ insert: param, ac-03.03_odp.01 }} is uniformly enforced across the covered subjects within the system;', true, 2, 5);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.3_obj.a-2', 'ac-3.3', 'ac-3.3_obj.a', '{{ insert: param, ac-03.03_odp.02 }} is uniformly enforced across the covered objects within the system;', true, 2, 6);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.3_obj.b.1', 'ac-3.3', 'ac-3.3_obj.b', '{{ insert: param, ac-03.03_odp.01 }} and {{ insert: param, ac-03.03_odp.02 }} specifying that a subject that has been granted access to information is constrained from passing the information to unauthorized subjects or objects are enforced;', true, 2, 8);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.3_obj.b.2', 'ac-3.3', 'ac-3.3_obj.b', '{{ insert: param, ac-03.03_odp.01 }} and {{ insert: param, ac-03.03_odp.02 }} specifying that a subject that has been granted access to information is constrained from granting its privileges to other subjects are enforced;', true, 2, 9);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.3_obj.b.3', 'ac-3.3', 'ac-3.3_obj.b', '{{ insert: param, ac-03.03_odp.01 }} and {{ insert: param, ac-03.03_odp.02 }} specifying that a subject that has been granted access to information is constrained from changing one of more security attributes (specified by the policy) on subjects, objects, the system, or system components are enforced;', true, 2, 10);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.3_obj.b.4', 'ac-3.3', 'ac-3.3_obj.b', '{{ insert: param, ac-03.03_odp.01 }} and {{ insert: param, ac-03.03_odp.02 }} specifying that a subject that has been granted access to information is constrained from choosing the security attributes and attribute values (specified by the policy) to be associated with newly created or modified objects are enforced;', true, 2, 11);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.3_obj.b.5', 'ac-3.3', 'ac-3.3_obj.b', '{{ insert: param, ac-03.03_odp.01 }} and {{ insert: param, ac-03.03_odp.02 }} specifying that a subject that has been granted access to information is constrained from changing the rules governing access control are enforced;', true, 2, 12);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.4_obj', 'ac-3.4', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.4_obj-1', 'ac-3.4', 'ac-3.4_obj', '{{ insert: param, ac-03.04_odp.01 }} is enforced over the set of covered subjects specified in the policy;', true, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.4_obj-2', 'ac-3.4', 'ac-3.4_obj', '{{ insert: param, ac-03.04_odp.02 }} is enforced over the set of covered objects specified in the policy;', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.4_obj.a', 'ac-3.4', 'ac-3.4_obj', '{{ insert: param, ac-03.04_odp.01 }} and {{ insert: param, ac-03.04_odp.02 }} are enforced where the policy specifies that a subject that has been granted access to information can pass the information to any other subjects or objects;', true, 1, 4);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.4_obj.b', 'ac-3.4', 'ac-3.4_obj', '{{ insert: param, ac-03.04_odp.01 }} and {{ insert: param, ac-03.04_odp.02 }} are enforced where the policy specifies that a subject that has been granted access to information can grant its privileges to other subjects;', true, 1, 5);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.4_obj.c', 'ac-3.4', 'ac-3.4_obj', '{{ insert: param, ac-03.04_odp.01 }} and {{ insert: param, ac-03.04_odp.02 }} are enforced where the policy specifies that a subject that has been granted access to information can change security attributes on subjects, objects, the system, or the system’s components;', true, 1, 6);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.4_obj.d', 'ac-3.4', 'ac-3.4_obj', '{{ insert: param, ac-03.04_odp.01 }} and {{ insert: param, ac-03.04_odp.02 }} are enforced where the policy specifies that a subject that has been granted access to information can choose the security attributes to be associated with newly created or revised objects;', true, 1, 7);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.4_obj.e', 'ac-3.4', 'ac-3.4_obj', '{{ insert: param, ac-03.04_odp.01 }} and {{ insert: param, ac-03.04_odp.02 }} are enforced where the policy specifies that a subject that has been granted access to information can change the rules governing access control.', true, 1, 8);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.5_obj', 'ac-3.5', null, 'access to {{ insert: param, ac-03.05_odp }} is prevented except during secure, non-operable system states.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.7_obj', 'ac-3.7', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.7_obj-1', 'ac-3.7', 'ac-3.7_obj', 'a role-based access control policy is enforced over defined subjects;', true, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.7_obj-2', 'ac-3.7', 'ac-3.7_obj', 'a role-based access control policy is enforced over defined objects;', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-3.7_obj-3', 'ac-3.7', 'ac-3.7_obj', 'access is controlled based on {{ insert: param, ac-03.07_odp.01 }} and {{ insert: param, ac-03.07_odp.02 }}.', true, 1, 4);
