insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-4.24_obj-2', 'ac-4.24', 'ac-4.24_obj', 'when transferring information between different security domains, the data is regenerated to be consistent with its intended specification.', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-4.25_obj', 'ac-4.25', null, 'when transferring information between different security domains, data is sanitized to minimize {{ insert: param, ac-04.25_odp.01 }} in accordance with {{ insert: param, ac-04.25_odp.02 }}.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-4.26_obj', 'ac-4.26', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-4.26_obj-1', 'ac-4.26', 'ac-4.26_obj', 'when transferring information between different security domains, content-filtering actions are recorded and audited;', true, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-4.26_obj-2', 'ac-4.26', 'ac-4.26_obj', 'when transferring information between different security domains, results for the information being filtered are recorded and audited.', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-4.27_obj', 'ac-4.27', null, 'when transferring information between security domains, implemented content filtering solutions provide redundant and independent filtering mechanisms for each data type.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-4.28_obj', 'ac-4.28', null, 'when transferring information between security domains, a linear content filter pipeline is implemented that is enforced with discretionary and mandatory access controls.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-4.29_obj', 'ac-4.29', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-4.29_obj.a', 'ac-4.29', 'ac-4.29_obj', 'when transferring information between security domains, content filter orchestration engines are employed to ensure that content-filtering mechanisms successfully complete execution without errors;', true, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-4.29_obj.b', 'ac-4.29', 'ac-4.29_obj', null, false, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-4.29_obj.b-1', 'ac-4.29', 'ac-4.29_obj.b', 'when transferring information between security domains, content filter orchestration engines are employed to ensure that content-filtering actions occur in the correct order;', true, 2, 4);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-4.29_obj.b-2', 'ac-4.29', 'ac-4.29_obj.b', 'when transferring information between security domains, content filter orchestration engines are employed to ensure that content-filtering actions comply with {{ insert: param, ac-04.29_odp }}.', true, 2, 5);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-4.3_obj', 'ac-4.3', null, '{{ insert: param, ac-04.03_odp }} are enforced.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-4.30_obj', 'ac-4.30', null, 'when transferring information between security domains, content-filtering mechanisms using multiple processes are implemented.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-4.31_obj', 'ac-4.31', null, 'when transferring information between different security domains, the transfer of failed content to the receiving domain is prevented.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-4.32_obj', 'ac-4.32', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-4.32_obj.a', 'ac-4.32', 'ac-4.32_obj', 'when transferring information between different security domains, the process that transfers information between filter pipelines does not filter message content;', true, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-4.32_obj.b', 'ac-4.32', 'ac-4.32_obj', 'when transferring information between different security domains, the process that transfers information between filter pipelines validates filtering metadata;', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-4.32_obj.c', 'ac-4.32', 'ac-4.32_obj', 'when transferring information between different security domains, the process that transfers information between filter pipelines ensures that the content with the filtering metadata has successfully completed filtering;', true, 1, 4);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-4.32_obj.d', 'ac-4.32', 'ac-4.32_obj', 'when transferring information between different security domains, the process that transfers information between filter pipelines transfers the content to the destination filter pipeline.', true, 1, 5);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-4.4_obj', 'ac-4.4', null, 'encrypted information is prevented from bypassing {{ insert: param, ac-04.04_odp.01 }} by {{ insert: param, ac-04.04_odp.02 }}.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-4.5_obj', 'ac-4.5', null, '{{ insert: param, ac-04.05_odp }} are enforced on embedding data types within other data types.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-4.6_obj', 'ac-4.6', null, 'information flow control enforcement is based on {{ insert: param, ac-04.06_odp }}.', true, 0, 1);
