insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-6.1_obj.a-1', 'ac-6.1', 'ac-6.1_obj.a', 'access is authorized for {{ insert: param, ac-06.01_odp.01 }} to {{ insert: param, ac-06.01_odp.02 }};', true, 2, 3);
