insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-6.3_obj-2', 'ac-6.3', 'ac-6.3_obj', 'the rationale for authorizing network access to privileged commands is documented in the security plan for the system.', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-6.4_obj', 'ac-6.4', null, 'separate processing domains are provided to enable finer-grain allocation of user privileges.', true, 0, 1);
