insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-6.7_obj.b', 'ac-6.7', 'ac-6.7_obj', 'privileges are reassigned or removed, if necessary, to correctly reflect organizational mission and business needs.', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-6.8_obj', 'ac-6.8', null, '{{ insert: param, ac-06.08_odp }} is prevented from executing at higher privilege levels than users executing the software.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-6.9_obj', 'ac-6.9', null, 'the execution of privileged functions is logged.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-7_obj', 'ac-7', null, null, false, 0, 1);
