insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-8_obj.b', 'ac-8', 'ac-8_obj', 'the notification message or banner is retained on the screen until users acknowledge the usage conditions and take explicit actions to log on to or further access the system;', true, 1, 7);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-8_obj.c', 'ac-8', 'ac-8_obj', null, false, 1, 8);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-8_obj.a.1', 'ac-8', 'ac-8_obj.a', 'the system use notification states that users are accessing a U.S. Government system;', true, 2, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-8_obj.a.2', 'ac-8', 'ac-8_obj.a', 'the system use notification states that system usage may be monitored, recorded, and subject to audit;', true, 2, 4);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-8_obj.a.3', 'ac-8', 'ac-8_obj.a', 'the system use notification states that unauthorized use of the system is prohibited and subject to criminal and civil penalties; and', true, 2, 5);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-8_obj.a.4', 'ac-8', 'ac-8_obj.a', 'the system use notification states that use of the system indicates consent to monitoring and recording;', true, 2, 6);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-8_obj.c.1', 'ac-8', 'ac-8_obj.c', 'for publicly accessible systems, system use information {{ insert: param, ac-08_odp.02 }} is displayed before granting further access to the publicly accessible system;', true, 2, 9);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-8_obj.c.2', 'ac-8', 'ac-8_obj.c', 'for publicly accessible systems, any references to monitoring, recording, or auditing that are consistent with privacy accommodations for such systems that generally prohibit those activities are displayed;', true, 2, 10);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-8_obj.c.3', 'ac-8', 'ac-8_obj.c', 'for publicly accessible systems, a description of the authorized uses of the system is included.', true, 2, 11);
