insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ac-9.4_obj', 'ac-9.4', null, 'the user is notified, upon successful logon, of {{ insert: param, ac-09.04_odp }}.', true, 0, 1);
