insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('au-3.1_obj', 'au-3.1', null, 'generated audit records contain the following {{ insert: param, au-03.01_odp }}.', true, 0, 1);
