insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('au-4_obj', 'au-4', null, 'audit log storage capacity is allocated to accommodate {{ insert: param, au-04_odp }}.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('au-4.1_obj', 'au-4.1', null, 'audit logs are transferred {{ insert: param, au-04.01_odp }} to a different system, system component, or media other than the system or system component conducting the logging.', true, 0, 1);
