insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('au-5.3_obj-2', 'au-5.3', 'au-5.3_obj', 'network traffic is {{ insert: param, au-05.03_odp }} if network traffic volume is above configured thresholds.', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('au-5.4_obj', 'au-5.4', null, '{{ insert: param, au-05.04_odp.01 }} is/are invoked in the event of {{ insert: param, au-05.04_odp.02 }} , unless an alternate audit logging capability exists.', true, 0, 1);
