insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-2_obj.c', 'ca-2', 'ca-2_obj', 'the control assessment plan is reviewed and approved by the authorizing official or designated representative prior to conducting the assessment;', true, 1, 10);
