insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-2_obj.e', 'ca-2', 'ca-2_obj', 'a control assessment report is produced that documents the results of the assessment;', true, 1, 14);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-2_obj.f', 'ca-2', 'ca-2_obj', 'the results of the control assessment are provided to {{ insert: param, ca-02_odp.02 }}.', true, 1, 15);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-2_obj.b.1', 'ca-2', 'ca-2_obj.b', 'a control assessment plan is developed that describes the scope of the assessment, including controls and control enhancements under assessment;', true, 2, 4);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-2_obj.b.2', 'ca-2', 'ca-2_obj.b', 'a control assessment plan is developed that describes the scope of the assessment, including assessment procedures to be used to determine control effectiveness;', true, 2, 5);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-2_obj.b.3', 'ca-2', 'ca-2_obj.b', null, false, 2, 6);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-2_obj.d-1', 'ca-2', 'ca-2_obj.d', 'controls are assessed in the system and its environment of operation {{ insert: param, ca-02_odp.01 }} to determine the extent to which the controls are implemented correctly, operating as intended, and producing the desired outcome with respect to meeting established security requirements;', true, 2, 12);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-2_obj.d-2', 'ca-2', 'ca-2_obj.d', 'controls are assessed in the system and its environment of operation {{ insert: param, ca-02_odp.01 }} to determine the extent to which the controls are implemented correctly, operating as intended, and producing the desired outcome with respect to meeting established privacy requirements;', true, 2, 13);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-2_obj.b.3-1', 'ca-2', 'ca-2_obj.b.3', 'a control assessment plan is developed that describes the scope of the assessment, including the assessment environment;', true, 3, 7);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-2_obj.b.3-2', 'ca-2', 'ca-2_obj.b.3', 'a control assessment plan is developed that describes the scope of the assessment, including the assessment team;', true, 3, 8);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-2_obj.b.3-3', 'ca-2', 'ca-2_obj.b.3', 'a control assessment plan is developed that describes the scope of the assessment, including assessment roles and responsibilities;', true, 3, 9);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-2.1_obj', 'ca-2.1', null, 'independent assessors or assessment teams are employed to conduct control assessments.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-2.2_obj', 'ca-2.2', null, '{{ insert: param, ca-02.02_odp.01 }} {{ insert: param, ca-02.02_odp.02 }} {{ insert: param, ca-02.02_odp.03 }} are included as part of control assessments.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-2.3_obj', 'ca-2.3', null, 'the results of control assessments performed by {{ insert: param, ca-02.03_odp.01 }} on {{ insert: param, ca-02.03_odp.02 }} are leveraged when the assessment meets {{ insert: param, ca-02.03_odp.03 }}.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-3_obj', 'ca-3', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-3_obj.a', 'ca-3', 'ca-3_obj', 'the exchange of information between the system and other systems is approved and managed using {{ insert: param, ca-03_odp.01 }};', true, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-3_obj.b', 'ca-3', 'ca-3_obj', null, false, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-3_obj.c', 'ca-3', 'ca-3_obj', 'agreements are reviewed and updated {{ insert: param, ca-03_odp.03 }}.', true, 1, 10);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-3_obj.b-1', 'ca-3', 'ca-3_obj.b', 'the interface characteristics are documented as part of each exchange agreement;', true, 2, 4);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-3_obj.b-2', 'ca-3', 'ca-3_obj.b', 'security requirements are documented as part of each exchange agreement;', true, 2, 5);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-3_obj.b-3', 'ca-3', 'ca-3_obj.b', 'privacy requirements are documented as part of each exchange agreement;', true, 2, 6);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-3_obj.b-4', 'ca-3', 'ca-3_obj.b', 'controls are documented as part of each exchange agreement;', true, 2, 7);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-3_obj.b-5', 'ca-3', 'ca-3_obj.b', 'responsibilities for each system are documented as part of each exchange agreement;', true, 2, 8);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-3_obj.b-6', 'ca-3', 'ca-3_obj.b', 'the impact level of the information communicated is documented as part of each exchange agreement;', true, 2, 9);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-3.6_obj', 'ca-3.6', null, 'individuals or systems transferring data between interconnecting systems have the requisite authorizations (i.e., write permissions or privileges) prior to accepting such data.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-3.7_obj', 'ca-3.7', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-3.7_obj.a', 'ca-3.7', 'ca-3.7_obj', 'transitive (downstream) information exchanges with other systems through the systems identified in CA-03a are identified;', true, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-3.7_obj.b', 'ca-3.7', 'ca-3.7_obj', 'measures are taken to ensure that transitive (downstream) information exchanges cease when the controls on identified transitive (downstream) systems cannot be verified or validated.', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-5_obj', 'ca-5', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-5_obj.a', 'ca-5', 'ca-5_obj', 'a plan of action and milestones for the system is developed to document the planned remediation actions of the organization to correct weaknesses or deficiencies noted during the assessment of the controls and to reduce or eliminate known vulnerabilities in the system;', true, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-5_obj.b', 'ca-5', 'ca-5_obj', 'existing plan of action and milestones are updated {{ insert: param, ca-05_odp }} based on the findings from control assessments, independent audits or reviews, and continuous monitoring activities.', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-5.1_obj', 'ca-5.1', null, '{{ insert: param, ca-05.01_odp }} are used to ensure the accuracy, currency, and availability of the plan of action and milestones for the system.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-6_obj', 'ca-6', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-6_obj.a', 'ca-6', 'ca-6_obj', 'a senior official is assigned as the authorizing official for the system;', true, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-6_obj.b', 'ca-6', 'ca-6_obj', 'a senior official is assigned as the authorizing official for common controls available for inheritance by organizational systems;', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-6_obj.c', 'ca-6', 'ca-6_obj', null, false, 1, 4);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-6_obj.d', 'ca-6', 'ca-6_obj', 'the authorizing official for common controls authorizes the use of those controls for inheritance by organizational systems;', true, 1, 7);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-6_obj.e', 'ca-6', 'ca-6_obj', 'the authorizations are updated {{ insert: param, ca-06_odp }}.', true, 1, 8);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-6_obj.c.1', 'ca-6', 'ca-6_obj.c', 'before commencing operations, the authorizing official for the system accepts the use of common controls inherited by the system;', true, 2, 5);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-6_obj.c.2', 'ca-6', 'ca-6_obj.c', 'before commencing operations, the authorizing official for the system authorizes the system to operate;', true, 2, 6);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-6.1_obj', 'ca-6.1', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-6.1_obj-1', 'ca-6.1', 'ca-6.1_obj', 'a joint authorization process is employed for the system;', true, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-6.1_obj-2', 'ca-6.1', 'ca-6.1_obj', 'the joint authorization process employed for the system includes multiple authorizing officials from the same organization conducting the authorization.', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-6.2_obj', 'ca-6.2', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-6.2_obj-1', 'ca-6.2', 'ca-6.2_obj', 'a joint authorization process is employed for the system;', true, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-6.2_obj-2', 'ca-6.2', 'ca-6.2_obj', 'the joint authorization process employed for the system includes multiple authorizing officials with at least one authorizing official from an organization external to the organization conducting the authorization.', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-7_obj', 'ca-7', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-7_obj-1', 'ca-7', 'ca-7_obj', 'a system-level continuous monitoring strategy is developed;', true, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-7_obj-2', 'ca-7', 'ca-7_obj', 'system-level continuous monitoring is implemented in accordance with the organization-level continuous monitoring strategy;', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-7_obj.a', 'ca-7', 'ca-7_obj', 'system-level continuous monitoring includes establishment of the following system-level metrics to be monitored: {{ insert: param, ca-07_odp.01 }};', true, 1, 4);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-7_obj.b', 'ca-7', 'ca-7_obj', null, false, 1, 5);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-7_obj.c', 'ca-7', 'ca-7_obj', 'system-level continuous monitoring includes ongoing control assessments in accordance with the continuous monitoring strategy;', true, 1, 8);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-7_obj.d', 'ca-7', 'ca-7_obj', 'system-level continuous monitoring includes ongoing monitoring of system and organization-defined metrics in accordance with the continuous monitoring strategy;', true, 1, 9);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-7_obj.e', 'ca-7', 'ca-7_obj', 'system-level continuous monitoring includes correlation and analysis of information generated by control assessments and monitoring;', true, 1, 10);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-7_obj.f', 'ca-7', 'ca-7_obj', 'system-level continuous monitoring includes response actions to address the results of the analysis of control assessment and monitoring information;', true, 1, 11);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-7_obj.g', 'ca-7', 'ca-7_obj', null, false, 1, 12);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-7_obj.b-1', 'ca-7', 'ca-7_obj.b', 'system-level continuous monitoring includes established {{ insert: param, ca-07_odp.02 }} for monitoring;', true, 2, 6);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-7_obj.b-2', 'ca-7', 'ca-7_obj.b', 'system-level continuous monitoring includes established {{ insert: param, ca-07_odp.03 }} for assessment of control effectiveness;', true, 2, 7);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-7_obj.g-1', 'ca-7', 'ca-7_obj.g', 'system-level continuous monitoring includes reporting the security status of the system to {{ insert: param, ca-07_odp.04 }} {{ insert: param, ca-07_odp.05 }};', true, 2, 13);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-7_obj.g-2', 'ca-7', 'ca-7_obj.g', 'system-level continuous monitoring includes reporting the privacy status of the system to {{ insert: param, ca-07_odp.06 }} {{ insert: param, ca-07_odp.07 }}.', true, 2, 14);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-7.1_obj', 'ca-7.1', null, 'independent assessors or assessment teams are employed to monitor the controls in the system on an ongoing basis.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-7.3_obj', 'ca-7.3', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-7.3_obj-1', 'ca-7.3', 'ca-7.3_obj', 'trend analysis is employed to determine if control implementations used in the continuous monitoring process need to be modified based on empirical data;', true, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-7.3_obj-2', 'ca-7.3', 'ca-7.3_obj', 'trend analysis is employed to determine if the frequency of continuous monitoring activities used in the continuous monitoring process needs to be modified based on empirical data;', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-7.3_obj-3', 'ca-7.3', 'ca-7.3_obj', 'trend analysis is employed to determine if the types of activities used in the continuous monitoring process need to be modified based on empirical data.', true, 1, 4);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-7.4_obj', 'ca-7.4', null, 'risk monitoring is an integral part of the continuous monitoring strategy;', false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-7.4_obj.a', 'ca-7.4', 'ca-7.4_obj', 'effectiveness monitoring is included in risk monitoring;', true, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-7.4_obj.b', 'ca-7.4', 'ca-7.4_obj', 'compliance monitoring is included in risk monitoring;', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-7.4_obj.c', 'ca-7.4', 'ca-7.4_obj', 'change monitoring is included in risk monitoring.', true, 1, 4);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-7.5_obj', 'ca-7.5', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-7.5_obj-1', 'ca-7.5', 'ca-7.5_obj', '{{ insert: param, ca-07.05_odp.01 }} are employed to validate that policies are established;', true, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-7.5_obj-2', 'ca-7.5', 'ca-7.5_obj', '{{ insert: param, ca-07.05_odp.02 }} are employed to validate that implemented controls are operating in a consistent manner.', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-7.6_obj', 'ca-7.6', null, '{{ insert: param, ca-07.06_odp }} are used to ensure the accuracy, currency, and availability of monitoring results for the system.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-8_obj', 'ca-8', null, 'penetration testing is conducted {{ insert: param, ca-08_odp.01 }} on {{ insert: param, ca-08_odp.02 }}.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-8.1_obj', 'ca-8.1', null, 'an independent penetration testing agent or team is employed to perform penetration testing on the system or system components.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-8.2_obj', 'ca-8.2', null, '{{ insert: param, ca-08.02_odp }} are employed to simulate attempts by adversaries to compromise organizational systems in accordance with applicable rules of engagement.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-8.3_obj', 'ca-8.3', null, 'the penetration testing process includes {{ insert: param, ca-08.03_odp.01 }} {{ insert: param, ca-08.03_odp.02 }} attempts to bypass or circumvent controls associated with physical access points to facility.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-9_obj', 'ca-9', null, null, false, 0, 1);
