insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-9_obj.b', 'ca-9', 'ca-9_obj', null, false, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-9_obj.c', 'ca-9', 'ca-9_obj', 'internal system connections are terminated after {{ insert: param, ca-09_odp.02 }};', true, 1, 8);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-9_obj.d', 'ca-9', 'ca-9_obj', 'the continued need for each internal connection is reviewed {{ insert: param, ca-09_odp.03 }}.', true, 1, 9);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-9_obj.b-1', 'ca-9', 'ca-9_obj.b', 'for each internal connection, the interface characteristics are documented;', true, 2, 4);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-9_obj.b-2', 'ca-9', 'ca-9_obj.b', 'for each internal connection, the security requirements are documented;', true, 2, 5);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-9_obj.b-3', 'ca-9', 'ca-9_obj.b', 'for each internal connection, the privacy requirements are documented;', true, 2, 6);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-9_obj.b-4', 'ca-9', 'ca-9_obj.b', 'for each internal connection, the nature of the information communicated is documented;', true, 2, 7);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-9.1_obj', 'ca-9.1', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-9.1_obj-1', 'ca-9.1', 'ca-9.1_obj', 'security compliance checks are performed on constituent system components prior to the establishment of the internal connection;', true, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ca-9.1_obj-2', 'ca-9.1', 'ca-9.1_obj', 'privacy compliance checks are performed on constituent system components prior to the establishment of the internal connection.', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('cm-1_obj', 'cm-1', null, null, false, 0, 1);
