insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('cm-7.7_obj', 'cm-7.7', null, 'the execution of binary or machine-executable code is only allowed in confined physical or virtual machine environments;', false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('cm-7.7_obj.a', 'cm-7.7', 'cm-7.7_obj', 'the execution of binary or machine-executable code obtained from sources with limited or no warranty is only allowed with the explicit approval of {{ insert: param, cm-07.07_odp }};', true, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('cm-7.7_obj.b', 'cm-7.7', 'cm-7.7_obj', 'the execution of binary or machine-executable code without the provision of source code is only allowed with the explicit approval of {{ insert: param, cm-07.07_odp }}.', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('cm-7.8_obj', 'cm-7.8', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('cm-7.8_obj.a', 'cm-7.8', 'cm-7.8_obj', 'the use of binary or machine-executable code is prohibited when it originates from sources with limited or no warranty or without the provision of source code;', true, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('cm-7.8_obj.b', 'cm-7.8', 'cm-7.8_obj', null, false, 1, 3);
