insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('cm-7.8_obj.b-2', 'cm-7.8', 'cm-7.8_obj.b', 'exceptions to the prohibition of binary or machine-executable code from sources with limited or no warranty or without the provision of source code are allowed only with the approval of the authorizing official.', true, 2, 5);
