insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('cp-7_obj.c', 'cp-7', 'cp-7_obj', 'controls provided at the alternate processing site are equivalent to those at the primary site.', true, 1, 6);
