insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('cp-7_obj.b-2', 'cp-7', 'cp-7_obj.b', 'the equipment and supplies required to resume operations are made available at the alternate processing site or if contracts are in place to support delivery to the site within {{ insert: param, cp-07_odp.02 }} for resumption;', true, 2, 5);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('cp-7.1_obj', 'cp-7.1', null, 'an alternate processing site that is sufficiently separated from the primary processing site to reduce susceptibility to the same threats is identified.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('cp-7.2_obj', 'cp-7.2', null, null, false, 0, 1);
