insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('cp-7.2_obj-2', 'cp-7.2', 'cp-7.2_obj', 'explicit mitigation actions to address identified accessibility problems are outlined.', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('cp-7.3_obj', 'cp-7.3', null, 'alternate processing site agreements that contain priority-of-service provisions in accordance with availability requirements (including recovery time objectives) are developed.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('cp-7.4_obj', 'cp-7.4', null, 'the alternate processing site is prepared so that the site can serve as the operational site supporting essential mission and business functions.', true, 0, 1);
