insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('cp-7.6_obj-1', 'cp-7.6', 'cp-7.6_obj', 'circumstances that preclude returning to the primary processing site are planned for;', true, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('cp-7.6_obj-2', 'cp-7.6', 'cp-7.6_obj', 'circumstances that preclude returning to the primary processing site are prepared for.', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('cp-8_obj', 'cp-8', null, 'alternate telecommunications services, including necessary agreements to permit the resumption of {{ insert: param, cp-08_odp.01 }} , are established for essential mission and business functions within {{ insert: param, cp-08_odp.02 }} when the primary telecommunications capabilities are unavailable at either the primary or alternate processing or storage sites.', true, 0, 1);
