insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('cp-8.1_obj.a-1', 'cp-8.1', 'cp-8.1_obj.a', 'primary telecommunications service agreements that contain priority-of-service provisions in accordance with availability requirements (including recovery time objectives) are developed;', true, 2, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('cp-8.1_obj.a-2', 'cp-8.1', 'cp-8.1_obj.a', 'alternate telecommunications service agreements that contain priority-of-service provisions in accordance with availability requirements (including recovery time objectives) are developed;', true, 2, 4);
