insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('cp-8.4_obj.a-2', 'cp-8.4', 'cp-8.4_obj.a', 'alternate telecommunications service providers are required to have contingency plans;', true, 2, 4);
