insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-13.1_obj-2', 'ia-13.1', 'ia-13.1_obj', 'cryptographic keys that protect access tokens are managed;', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-13.1_obj-3', 'ia-13.1', 'ia-13.1_obj', 'cryptographic keys that protect access tokens are protected from disclosure; and', true, 1, 4);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-13.1_obj-4', 'ia-13.1', 'ia-13.1_obj', 'cryptographic keys that protect access tokens are protected from disclosure and misuse', true, 1, 5);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-13.2_obj', 'ia-13.2', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-13.2_obj-1', 'ia-13.2', 'ia-13.2_obj', 'the source of identity assertions is verified before granting access to system and information resources;', true, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-13.2_obj-2', 'ia-13.2', 'ia-13.2_obj', 'the source of access tokens is verified before granting access to system and information resources;', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-13.2_obj-3', 'ia-13.2', 'ia-13.2_obj', 'the integrity of identity assertions is verified before granting access to system and information resources;', true, 1, 4);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-13.2_obj-4', 'ia-13.2', 'ia-13.2_obj', 'the integrity of access tokens is verified before granting access to system and information resources', true, 1, 5);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-13.3_obj', 'ia-13.3', null, null, false, 0, 1);
