insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-13.3_obj.a-2', 'ia-13.3', 'ia-13.3_obj', 'access tokens are generated in accordance with {{ insert: param, ia-13_odp.01 }};', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-13.3_obj.b-1', 'ia-13.3', 'ia-13.3_obj', 'assertions are issued in accordance with {{ insert: param, ia-13_odp.01 }};', true, 1, 4);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-13.3_obj.b-2', 'ia-13.3', 'ia-13.3_obj', 'access tokens are issued in accordance with {{ insert: param, ia-13_odp.01 }};', true, 1, 5);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-13.3_obj.c-1', 'ia-13.3', 'ia-13.3_obj', 'assertions are refreshed in accordance with {{ insert: param, ia-13_odp.01 }};', true, 1, 6);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-13.3_obj.c-2', 'ia-13.3', 'ia-13.3_obj', 'access tokens are refreshed in accordance with {{ insert: param, ia-13_odp.01 }};', true, 1, 7);
