insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-13.3_obj.d-2', 'ia-13.3', 'ia-13.3_obj', 'access tokens are revoked in accordance with {{ insert: param, ia-13_odp.01 }};', true, 1, 9);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-13.3_obj.e-1', 'ia-13.3', 'ia-13.3_obj', 'assertions are time-restricted in accordance with {{ insert: param, ia-13_odp.01 }};', true, 1, 10);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-13.3_obj.e-2', 'ia-13.3', 'ia-13.3_obj', 'access tokens are time-restricted in accordance with {{ insert: param, ia-13_odp.01 }};', true, 1, 11);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-13.3_obj.f-1', 'ia-13.3', 'ia-13.3_obj', 'assertions are audience-restricted in accordance with {{ insert: param, ia-13_odp.01 }};', true, 1, 12);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-13.3_obj.f-2', 'ia-13.3', 'ia-13.3_obj', 'access tokens are audience-restricted in accordance with {{ insert: param, ia-13_odp.01 }};', true, 1, 13);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-2_obj', 'ia-2', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-2_obj-1', 'ia-2', 'ia-2_obj', 'organizational users are uniquely identified and authenticated;', true, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-2_obj-2', 'ia-2', 'ia-2_obj', 'the unique identification of authenticated organizational users is associated with processes acting on behalf of those users.', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-2.1_obj', 'ia-2.1', null, 'multi-factor authentication is implemented for access to privileged accounts.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-2.10_obj', 'ia-2.10', null, 'a single sign-on capability is provided for {{ insert: param, ia-02.10_odp }}.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-2.12_obj', 'ia-2.12', null, 'Personal Identity Verification-compliant credentials are accepted and electronically verified.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-2.13_obj', 'ia-2.13', null, '{{ insert: param, ia-02.13_odp.01 }} mechanisms are implemented under {{ insert: param, ia-02.13_odp.02 }}.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-2.2_obj', 'ia-2.2', null, 'multi-factor authentication for access to non-privileged accounts is implemented.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-2.5_obj', 'ia-2.5', null, 'users are required to be individually authenticated before granting access to the shared accounts or resources when shared accounts or authenticators are employed.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-2.6_obj', 'ia-2.6', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-2.6_obj.a', 'ia-2.6', 'ia-2.6_obj', 'multi-factor authentication is implemented for {{ insert: param, ia-02.06_odp.01 }} access to {{ insert: param, ia-02.06_odp.02 }} such that one of the factors is provided by a device separate from the system gaining access;', true, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-2.6_obj.b', 'ia-2.6', 'ia-2.6_obj', 'multi-factor authentication is implemented for {{ insert: param, ia-02.06_odp.01 }} access to {{ insert: param, ia-02.06_odp.02 }} such that the device meets {{ insert: param, ia-02.06_odp.03 }}.', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-2.8_obj', 'ia-2.8', null, 'replay-resistant authentication mechanisms for access to {{ insert: param, ia-02.08_odp }} are implemented.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-3_obj', 'ia-3', null, '{{ insert: param, ia-03_odp.01 }} are uniquely identified and authenticated before establishing a {{ insert: param, ia-03_odp.02 }} connection.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-3.1_obj', 'ia-3.1', null, '{{ insert: param, ia-03.01_odp.01 }} are authenticated before establishing {{ insert: param, ia-03.01_odp.02 }} connection using bidirectional authentication that is cryptographically based.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-3.3_obj', 'ia-3.3', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-3.3_obj.a', 'ia-3.3', 'ia-3.3_obj', null, false, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-3.3_obj.b', 'ia-3.3', 'ia-3.3_obj', 'lease information is audited when assigned to a device.', true, 1, 5);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-3.3_obj.a-1', 'ia-3.3', 'ia-3.3_obj.a', 'dynamic address allocation lease information assigned to devices where addresses are allocated dynamically are standardized in accordance with {{ insert: param, ia-03.03_odp.01 }};', true, 2, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-3.3_obj.a-2', 'ia-3.3', 'ia-3.3_obj.a', 'dynamic address allocation lease duration assigned to devices where addresses are allocated dynamically are standardized in accordance with {{ insert: param, ia-03.03_odp.02 }};', true, 2, 4);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-3.4_obj', 'ia-3.4', null, 'device identification and authentication are handled based on attestation by {{ insert: param, ia-03.04_odp }}.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-4_obj', 'ia-4', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-4_obj.a', 'ia-4', 'ia-4_obj', 'system identifiers are managed by receiving authorization from {{ insert: param, ia-04_odp.01 }} to assign to an individual, group, role, or device identifier;', true, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-4_obj.b', 'ia-4', 'ia-4_obj', 'system identifiers are managed by selecting an identifier that identifies an individual, group, role, service, or device;', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-4_obj.c', 'ia-4', 'ia-4_obj', 'system identifiers are managed by assigning the identifier to the intended individual, group, role, service, or device;', true, 1, 4);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-4_obj.d', 'ia-4', 'ia-4_obj', 'system identifiers are managed by preventing reuse of identifiers for {{ insert: param, ia-04_odp.02 }}.', true, 1, 5);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-4.1_obj', 'ia-4.1', null, 'the use of system account identifiers that are the same as public identifiers is prohibited for individual accounts.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-4.4_obj', 'ia-4.4', null, 'individual identifiers are managed by uniquely identifying each individual as {{ insert: param, ia-04.04_odp }}.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-4.5_obj', 'ia-4.5', null, 'individual identifiers are dynamically managed in accordance with {{ insert: param, ia-04.05_odp }}.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-4.6_obj', 'ia-4.6', null, 'cross-organization management of identifiers is coordinated with {{ insert: param, ia-04.06_odp }}.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-4.8_obj', 'ia-4.8', null, 'pairwise pseudonymous identifiers are generated.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-4.9_obj', 'ia-4.9', null, 'the attributes for each uniquely identified individual, device, or service are maintained in {{ insert: param, ia-04.09_odp }}.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-5_obj', 'ia-5', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-5_obj.a', 'ia-5', 'ia-5_obj', 'system authenticators are managed through the verification of the identity of the individual, group, role, service, or device receiving the authenticator as part of the initial authenticator distribution;', true, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-5_obj.b', 'ia-5', 'ia-5_obj', 'system authenticators are managed through the establishment of initial authenticator content for any authenticators issued by the organization;', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-5_obj.c', 'ia-5', 'ia-5_obj', 'system authenticators are managed to ensure that authenticators have sufficient strength of mechanism for their intended use;', true, 1, 4);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-5_obj.d', 'ia-5', 'ia-5_obj', 'system authenticators are managed through the establishment and implementation of administrative procedures for initial authenticator distribution; lost, compromised, or damaged authenticators; and the revocation of authenticators;', true, 1, 5);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-5_obj.e', 'ia-5', 'ia-5_obj', 'system authenticators are managed through the change of default authenticators prior to first use;', true, 1, 6);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-5_obj.f', 'ia-5', 'ia-5_obj', 'system authenticators are managed through the change or refreshment of authenticators {{ insert: param, ia-05_odp.01 }} or when {{ insert: param, ia-05_odp.02 }} occur;', true, 1, 7);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-5_obj.g', 'ia-5', 'ia-5_obj', 'system authenticators are managed through the protection of authenticator content from unauthorized disclosure and modification;', true, 1, 8);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-5_obj.h', 'ia-5', 'ia-5_obj', null, false, 1, 9);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-5_obj.i', 'ia-5', 'ia-5_obj', 'system authenticators are managed through the change of authenticators for group or role accounts when membership to those accounts changes.', true, 1, 12);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-5_obj.h-1', 'ia-5', 'ia-5_obj.h', 'system authenticators are managed through the requirement for individuals to take specific controls to protect authenticators;', true, 2, 10);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-5_obj.h-2', 'ia-5', 'ia-5_obj.h', 'system authenticators are managed through the requirement for devices to implement specific controls to protect authenticators;', true, 2, 11);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-5.1_obj', 'ia-5.1', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-5.1_obj.a', 'ia-5.1', 'ia-5.1_obj', 'for password-based authentication, a list of commonly used, expected, or compromised passwords is maintained and updated {{ insert: param, ia-05.01_odp.01 }} and when organizational passwords are suspected to have been compromised directly or indirectly;', true, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-5.1_obj.b', 'ia-5.1', 'ia-5.1_obj', 'for password-based authentication when passwords are created or updated by users, the passwords are verified not to be found on the list of commonly used, expected, or compromised passwords in IA-05(01)(a);', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-5.1_obj.c', 'ia-5.1', 'ia-5.1_obj', 'for password-based authentication, passwords are only transmitted over cryptographically protected channels;', true, 1, 4);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-5.1_obj.d', 'ia-5.1', 'ia-5.1_obj', 'for password-based authentication, passwords are stored using an approved salted key derivation function, preferably using a keyed hash;', true, 1, 5);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-5.1_obj.e', 'ia-5.1', 'ia-5.1_obj', 'for password-based authentication, immediate selection of a new password is required upon account recovery;', true, 1, 6);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-5.1_obj.f', 'ia-5.1', 'ia-5.1_obj', 'for password-based authentication, user selection of long passwords and passphrases is allowed, including spaces and all printable characters;', true, 1, 7);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-5.1_obj.g', 'ia-5.1', 'ia-5.1_obj', 'for password-based authentication, automated tools are employed to assist the user in selecting strong password authenticators;', true, 1, 8);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-5.1_obj.h', 'ia-5.1', 'ia-5.1_obj', 'for password-based authentication, {{ insert: param, ia-05.01_odp.02 }} are enforced.', true, 1, 9);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-5.10_obj', 'ia-5.10', null, 'identities and authenticators are dynamically bound using {{ insert: param, ia-05.10_odp }}.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-5.12_obj', 'ia-5.12', null, 'mechanisms that satisfy {{ insert: param, ia-05.12_odp }} are employed for biometric-based authentication.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-5.13_obj', 'ia-5.13', null, 'the use of cached authenticators is prohibited after {{ insert: param, ia-05.13_odp }}.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-5.14_obj', 'ia-5.14', null, 'an organization-wide methodology for managing the content of PKI trust stores is employed across all platforms, including networks, operating systems, browsers, and applications for PKI-based authentication.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-5.15_obj', 'ia-5.15', null, 'only General Services Administration-approved products and services are used for identity, credential, and access management.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-5.16_obj', 'ia-5.16', null, 'the issuance of {{ insert: param, ia-05.16_odp.01 }} is required to be conducted {{ insert: param, ia-05.16_odp.02 }} before {{ insert: param, ia-05.16_odp.03 }} with authorization by {{ insert: param, ia-05.16_odp.04 }}.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-5.17_obj', 'ia-5.17', null, 'presentation attack detection mechanisms are employed for biometric-based authentication.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-5.18_obj', 'ia-5.18', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-5.18_obj.a', 'ia-5.18', 'ia-5.18_obj', '{{ insert: param, ia-05.18_odp.01 }} are employed to generate and manage passwords;', true, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-5.18_obj.b', 'ia-5.18', 'ia-5.18_obj', 'the passwords are protected using {{ insert: param, ia-05.18_odp.02 }}.', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-5.2_obj', 'ia-5.2', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-5.2_obj.a', 'ia-5.2', 'ia-5.2_obj', null, false, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-5.2_obj.b', 'ia-5.2', 'ia-5.2_obj', null, false, 1, 5);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-5.2_obj.a.1', 'ia-5.2', 'ia-5.2_obj.a', 'authorized access to the corresponding private key is enforced for public key-based authentication;', true, 2, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-5.2_obj.a.2', 'ia-5.2', 'ia-5.2_obj.a', 'the authenticated identity is mapped to the account of the individual or group for public key-based authentication;', true, 2, 4);
