insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-5.2_obj.b.2', 'ia-5.2', 'ia-5.2_obj.b', 'when public key infrastructure (PKI) is used, a local cache of revocation data is implemented to support path discovery and validation.', true, 2, 7);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-5.5_obj', 'ia-5.5', null, 'developers and installers of system components are required to provide unique authenticators or change default authenticators prior to delivery and installation.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ia-5.6_obj', 'ia-5.6', null, 'authenticators are protected commensurate with the security category of the information to which use of the authenticator permits access.', true, 0, 1);
