insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-2_obj.c', 'ma-2', 'ma-2_obj', '{{ insert: param, ma-02_odp.01 }} is/are required to explicitly approve the removal of the system or system components from organizational facilities for off-site maintenance, repair, or replacement;', true, 1, 9);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-2_obj.d', 'ma-2', 'ma-2_obj', 'equipment is sanitized to remove {{ insert: param, ma-02_odp.02 }} from associated media prior to removal from organizational facilities for off-site maintenance, repair, or replacement;', true, 1, 10);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-2_obj.e', 'ma-2', 'ma-2_obj', 'all potentially impacted controls are checked to verify that the controls are still functioning properly following maintenance, repair, or replacement actions;', true, 1, 11);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-2_obj.f', 'ma-2', 'ma-2_obj', '{{ insert: param, ma-02_odp.03 }} is included in organizational maintenance records.', true, 1, 12);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-2_obj.a-1', 'ma-2', 'ma-2_obj.a', 'maintenance, repair, and replacement of system components are scheduled in accordance with manufacturer or vendor specifications and/or organizational requirements;', true, 2, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-2_obj.a-2', 'ma-2', 'ma-2_obj.a', 'maintenance, repair, and replacement of system components are documented in accordance with manufacturer or vendor specifications and/or organizational requirements;', true, 2, 4);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-2_obj.a-3', 'ma-2', 'ma-2_obj.a', 'records of maintenance, repair, and replacement of system components are reviewed in accordance with manufacturer or vendor specifications and/or organizational requirements;', true, 2, 5);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-2_obj.b-1', 'ma-2', 'ma-2_obj.b', 'all maintenance activities, whether performed on site or remotely and whether the system or system components are serviced on site or removed to another location, are approved;', true, 2, 7);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-2_obj.b-2', 'ma-2', 'ma-2_obj.b', 'all maintenance activities, whether performed on site or remotely and whether the system or system components are serviced on site or removed to another location, are monitored;', true, 2, 8);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-2.2_obj', 'ma-2.2', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-2.2_obj.a', 'ma-2.2', 'ma-2.2_obj', null, false, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-2.2_obj.b', 'ma-2.2', 'ma-2.2_obj', null, false, 1, 6);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-2.2_obj.a-1', 'ma-2.2', 'ma-2.2_obj.a', '{{ insert: param, ma-02.02_odp.01 }} are used to schedule maintenance, repair, and replacement actions for the system;', true, 2, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-2.2_obj.a-2', 'ma-2.2', 'ma-2.2_obj.a', '{{ insert: param, ma-02.02_odp.02 }} are used to conduct maintenance, repair, and replacement actions for the system;', true, 2, 4);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-2.2_obj.a-3', 'ma-2.2', 'ma-2.2_obj.a', '{{ insert: param, ma-02.02_odp.03 }} are used to document maintenance, repair, and replacement actions for the system;', true, 2, 5);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-2.2_obj.b-1', 'ma-2.2', 'ma-2.2_obj.b', 'up-to date, accurate, and complete records of all maintenance actions requested, scheduled, in process, and completed are produced.', true, 2, 7);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-2.2_obj.b-2', 'ma-2.2', 'ma-2.2_obj.b', 'up-to date, accurate, and complete records of all repair actions requested, scheduled, in process, and completed are produced.', true, 2, 8);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-2.2_obj.b-3', 'ma-2.2', 'ma-2.2_obj.b', 'up-to date, accurate, and complete records of all replacement actions requested, scheduled, in process, and completed are produced.', true, 2, 9);
