insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-3_obj.a-1', 'ma-3', 'ma-3_obj.a', 'the use of system maintenance tools is approved;', true, 2, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-3_obj.a-2', 'ma-3', 'ma-3_obj.a', 'the use of system maintenance tools is controlled;', true, 2, 4);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-3_obj.a-3', 'ma-3', 'ma-3_obj.a', 'the use of system maintenance tools is monitored;', true, 2, 5);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-3.1_obj', 'ma-3.1', null, 'maintenance tools used by maintenance personnel are inspected for improper or unauthorized modifications.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-3.2_obj', 'ma-3.2', null, 'media containing diagnostic and test programs are checked for malicious code before the media are used in the system.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-3.3_obj', 'ma-3.3', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-3.3_obj.a', 'ma-3.3', 'ma-3.3_obj', 'the removal of maintenance equipment containing organizational information is prevented by verifying that there is no organizational information contained on the equipment; or', true, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-3.3_obj.b', 'ma-3.3', 'ma-3.3_obj', 'the removal of maintenance equipment containing organizational information is prevented by sanitizing or destroying the equipment; or', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-3.3_obj.c', 'ma-3.3', 'ma-3.3_obj', 'the removal of maintenance equipment containing organizational information is prevented by retaining the equipment within the facility; or', true, 1, 4);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-3.3_obj.d', 'ma-3.3', 'ma-3.3_obj', 'the removal of maintenance equipment containing organizational information is prevented by obtaining an exemption from {{ insert: param, ma-03.03_odp }} explicitly authorizing removal of the equipment from the facility.', true, 1, 5);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-3.4_obj', 'ma-3.4', null, 'the use of maintenance tools is restricted to authorized personnel only.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-3.5_obj', 'ma-3.5', null, 'the use of maintenance tools that execute with increased privilege is monitored.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-3.6_obj', 'ma-3.6', null, 'maintenance tools are inspected to ensure that the latest software updates and patches are installed.', true, 0, 1);
