insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-4_obj.c', 'ma-4', 'ma-4_obj', 'strong authentication is employed in the establishment of nonlocal maintenance and diagnostic sessions;', true, 1, 8);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-4_obj.d', 'ma-4', 'ma-4_obj', 'records for nonlocal maintenance and diagnostic activities are maintained;', true, 1, 9);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-4_obj.e', 'ma-4', 'ma-4_obj', null, false, 1, 10);
