insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-4_obj.a-2', 'ma-4', 'ma-4_obj.a', 'nonlocal maintenance and diagnostic activities are monitored;', true, 2, 4);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-4_obj.b-1', 'ma-4', 'ma-4_obj.b', 'the use of nonlocal maintenance and diagnostic tools are allowed only as consistent with organizational policy;', true, 2, 6);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-4_obj.b-2', 'ma-4', 'ma-4_obj.b', 'the use of nonlocal maintenance and diagnostic tools are documented in the security plan for the system;', true, 2, 7);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-4_obj.e-1', 'ma-4', 'ma-4_obj.e', 'session connections are terminated when nonlocal maintenance is completed;', true, 2, 11);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-4_obj.e-2', 'ma-4', 'ma-4_obj.e', 'network connections are terminated when nonlocal maintenance is completed.', true, 2, 12);
