insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-4.1_obj.a-1', 'ma-4.1', 'ma-4.1_obj.a', '{{ insert: param, ma-04.01_odp.01 }} are logged for nonlocal maintenance sessions;', true, 2, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-4.1_obj.a-2', 'ma-4.1', 'ma-4.1_obj.a', '{{ insert: param, ma-04.01_odp.02 }} are logged for nonlocal diagnostic sessions;', true, 2, 4);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-4.1_obj.b-1', 'ma-4.1', 'ma-4.1_obj.b', 'the audit records of the maintenance sessions are reviewed to detect anomalous behavior;', true, 2, 6);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-4.1_obj.b-2', 'ma-4.1', 'ma-4.1_obj.b', 'the audit records of the diagnostic sessions are reviewed to detect anomalous behavior.', true, 2, 7);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-4.3_obj', 'ma-4.3', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-4.3_obj.a', 'ma-4.3', 'ma-4.3_obj', null, false, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-4.3_obj.b', 'ma-4.3', 'ma-4.3_obj', null, false, 1, 5);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-4.3_obj.a-1', 'ma-4.3', 'ma-4.3_obj.a', 'nonlocal maintenance services are required to be performed from a system that implements a security capability comparable to the capability implemented on the system being serviced;', true, 2, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-4.3_obj.a-2', 'ma-4.3', 'ma-4.3_obj.a', 'nonlocal diagnostic services are required to be performed from a system that implements a security capability comparable to the capability implemented on the system being serviced; or', true, 2, 4);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-4.3_obj.b-1', 'ma-4.3', 'ma-4.3_obj.b', 'the component to be serviced is removed from the system prior to nonlocal maintenance or diagnostic services;', true, 2, 6);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-4.3_obj.b-2', 'ma-4.3', 'ma-4.3_obj.b', 'the component to be serviced is sanitized (for organizational information);', true, 2, 7);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-4.3_obj.b-3', 'ma-4.3', 'ma-4.3_obj.b', 'the component is inspected and sanitized (for potentially malicious software) after the service is performed and before reconnecting the component to the system.', true, 2, 8);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-4.4_obj', 'ma-4.4', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-4.4_obj.a', 'ma-4.4', 'ma-4.4_obj', 'nonlocal maintenance sessions are protected by employing {{ insert: param, ma-04.04_odp }};', true, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-4.4_obj.b', 'ma-4.4', 'ma-4.4_obj', null, false, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-4.4_obj.b.1', 'ma-4.4', 'ma-4.4_obj.b', 'nonlocal maintenance sessions are protected by separating maintenance sessions from other network sessions with the system by physically separated communication paths; or', true, 2, 4);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-4.4_obj.b.2', 'ma-4.4', 'ma-4.4_obj.b', 'nonlocal maintenance sessions are protected by logically separated communication paths.', true, 2, 5);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-4.5_obj', 'ma-4.5', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-4.5_obj.a', 'ma-4.5', 'ma-4.5_obj', 'the approval of each nonlocal maintenance session is required by {{ insert: param, ma-04.05_odp.01 }};', true, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-4.5_obj.b', 'ma-4.5', 'ma-4.5_obj', '{{ insert: param, ma-04.05_odp.02 }} is/are notified of the date and time of planned nonlocal maintenance.', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-4.6_obj', 'ma-4.6', null, null, false, 0, 1);
