insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-4.6_obj-2', 'ma-4.6', 'ma-4.6_obj', '{{ insert: param, ma-04.06_odp }} are implemented to protect the confidentiality of nonlocal maintenance and diagnostic communications.', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-4.7_obj', 'ma-4.7', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-4.7_obj-1', 'ma-4.7', 'ma-4.7_obj', 'session connection termination is verified after the completion of nonlocal maintenance and diagnostic sessions;', true, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-4.7_obj-2', 'ma-4.7', 'ma-4.7_obj', 'network connection termination is verified after the completion of nonlocal maintenance and diagnostic sessions.', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-5_obj', 'ma-5', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-5_obj.a', 'ma-5', 'ma-5_obj', null, false, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-5_obj.b', 'ma-5', 'ma-5_obj', 'non-escorted personnel performing maintenance on the system possess the required access authorizations;', true, 1, 5);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-5_obj.c', 'ma-5', 'ma-5_obj', 'organizational personnel with required access authorizations and technical competence is/are designated to supervise the maintenance activities of personnel who do not possess the required access authorizations.', true, 1, 6);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ma-5_obj.a-1', 'ma-5', 'ma-5_obj.a', 'a process for maintenance personnel authorization is established;', true, 2, 3);
