insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ps-3_obj.b-2', 'ps-3', 'ps-3_obj.b', 'where rescreening is so indicated, individuals are rescreened {{ insert: param, ps-03_odp.02 }}.', true, 2, 5);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ps-3.1_obj', 'ps-3.1', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ps-3.1_obj-1', 'ps-3.1', 'ps-3.1_obj', 'individuals accessing a system processing, storing, or transmitting classified information are cleared;', true, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ps-3.1_obj-2', 'ps-3.1', 'ps-3.1_obj', 'individuals accessing a system processing, storing, or transmitting classified information are indoctrinated to the highest classification level of the information to which they have access on the system.', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ps-3.2_obj', 'ps-3.2', null, 'individuals accessing a system processing, storing, or transmitting types of classified information that require formal indoctrination are formally indoctrinated for all of the relevant types of information to which they have access on the system.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ps-3.3_obj', 'ps-3.3', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ps-3.3_obj.a', 'ps-3.3', 'ps-3.3_obj', 'individuals accessing a system processing, storing, or transmitting information requiring special protection have valid access authorizations that are demonstrated by assigned official government duties;', true, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ps-3.3_obj.b', 'ps-3.3', 'ps-3.3_obj', 'individuals accessing a system processing, storing, or transmitting information requiring special protection satisfy {{ insert: param, ps-03.03_odp }}.', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ps-3.4_obj', 'ps-3.4', null, 'individuals accessing a system processing, storing, or transmitting {{ insert: param, ps-03.04_odp.01 }} meet {{ insert: param, ps-03.04_odp.02 }}.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ps-4_obj', 'ps-4', null, null, false, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ps-4_obj.a', 'ps-4', 'ps-4_obj', 'upon termination of individual employment, system access is disabled within {{ insert: param, ps-04_odp.01 }};', true, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ps-4_obj.b', 'ps-4', 'ps-4_obj', 'upon termination of individual employment, any authenticators and credentials are terminated or revoked;', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ps-4_obj.c', 'ps-4', 'ps-4_obj', 'upon termination of individual employment, exit interviews that include a discussion of {{ insert: param, ps-04_odp.02 }} are conducted;', true, 1, 4);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ps-4_obj.d', 'ps-4', 'ps-4_obj', 'upon termination of individual employment, all security-related organizational system-related property is retrieved;', true, 1, 5);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ps-4_obj.e', 'ps-4', 'ps-4_obj', 'upon termination of individual employment, access to organizational information and systems formerly controlled by the terminated individual are retained.', true, 1, 6);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ps-4.1_obj', 'ps-4.1', null, null, false, 0, 1);
