insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ps-5_obj.b', 'ps-5', 'ps-5_obj', '{{ insert: param, ps-05_odp.01 }} are initiated within {{ insert: param, ps-05_odp.02 }};', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ps-5_obj.c', 'ps-5', 'ps-5_obj', 'access authorization is modified as needed to correspond with any changes in operational need due to reassignment or transfer;', true, 1, 4);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ps-5_obj.d', 'ps-5', 'ps-5_obj', '{{ insert: param, ps-05_odp.03 }} are notified within {{ insert: param, ps-05_odp.04 }}.', true, 1, 5);
