insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('pt-2_obj.b', 'pt-2', 'pt-2_obj', 'the {{ insert: param, pt-02_odp.03 }} of personally identifiable information is restricted to only that which is authorized.', true, 1, 3);
