insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('pt-2.2_obj', 'pt-2.2', null, 'enforcement of the authorized processing of personally identifiable information is managed using {{ insert: param, pt-02.02_odp }}.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('pt-3_obj', 'pt-3', null, null, false, 0, 1);
