insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('pt-8_obj.b', 'pt-8', 'pt-8_obj', null, false, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('pt-8_obj.c', 'pt-8', 'pt-8_obj', 'a matching notice is published in the Federal Register when a system or organization processes information for the purpose of conducting a matching program;', true, 1, 6);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('pt-8_obj.d', 'pt-8', 'pt-8_obj', 'the information produced by the matching program is independently verified before taking adverse action against an individual, if required, when a system or organization processes information for the purpose of conducting a matching program;', true, 1, 7);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('pt-8_obj.e', 'pt-8', 'pt-8_obj', null, false, 1, 8);
