insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('pt-8_obj.b-2', 'pt-8', 'pt-8_obj.b', 'a computer matching agreement is entered into when a system or organization processes information for the purpose of conducting a matching program;', true, 2, 5);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('pt-8_obj.e-1', 'pt-8', 'pt-8_obj.e', 'individuals are provided with notice when a system or organization processes information for the purpose of conducting a matching program;', true, 2, 9);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('pt-8_obj.e-2', 'pt-8', 'pt-8_obj.e', 'individuals are provided with an opportunity to contest the findings before adverse action is taken against them when a system or organization processes information for the purpose of conducting a matching program.', true, 2, 10);
