insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ra-10_obj.b', 'ra-10', 'ra-10_obj', 'the threat hunting capability is employed {{ insert: param, ra-10_odp }}.', true, 1, 5);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ra-10_obj.a.1', 'ra-10', 'ra-10_obj.a', 'a cyber threat capability is established and maintained to search for indicators of compromise in organizational systems;', true, 2, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ra-10_obj.a.2', 'ra-10', 'ra-10_obj.a', 'a cyber threat capability is established and maintained to detect, track, and disrupt threats that evade existing controls;', true, 2, 4);
