insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ra-2_obj.a', 'ra-2', 'ra-2_obj', 'the system and the information it processes, stores, and transmits are categorized;', true, 1, 2);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ra-2_obj.b', 'ra-2', 'ra-2_obj', 'the security categorization results, including supporting rationale, are documented in the security plan for the system;', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ra-2_obj.c', 'ra-2', 'ra-2_obj', 'the authorizing official or authorizing official designated representative reviews and approves the security categorization decision.', true, 1, 4);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ra-2.1_obj', 'ra-2.1', null, 'an impact-level prioritization of organizational systems is conducted to obtain additional granularity on system impact levels.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ra-3_obj', 'ra-3', null, null, false, 0, 1);
