insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ra-3_obj.b', 'ra-3', 'ra-3_obj', 'risk assessment results and risk management decisions from the organization and mission or business process perspectives are integrated with system-level risk assessments;', true, 1, 6);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ra-3_obj.c', 'ra-3', 'ra-3_obj', 'risk assessment results are documented in {{ insert: param, ra-03_odp.01 }};', true, 1, 7);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ra-3_obj.d', 'ra-3', 'ra-3_obj', 'risk assessment results are reviewed {{ insert: param, ra-03_odp.03 }};', true, 1, 8);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ra-3_obj.e', 'ra-3', 'ra-3_obj', 'risk assessment results are disseminated to {{ insert: param, ra-03_odp.04 }};', true, 1, 9);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ra-3_obj.f', 'ra-3', 'ra-3_obj', 'the risk assessment is updated {{ insert: param, ra-03_odp.05 }} or when there are significant changes to the system, its environment of operation, or other conditions that may impact the security or privacy state of the system.', true, 1, 10);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ra-3_obj.a.1', 'ra-3', 'ra-3_obj.a', 'a risk assessment is conducted to identify threats to and vulnerabilities in the system;', true, 2, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ra-3_obj.a.2', 'ra-3', 'ra-3_obj.a', 'a risk assessment is conducted to determine the likelihood and magnitude of harm from unauthorized access, use, disclosure, disruption, modification, or destruction of the system; the information it processes, stores, or transmits; and any related information;', true, 2, 4);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ra-3_obj.a.3', 'ra-3', 'ra-3_obj.a', 'a risk assessment is conducted to determine the likelihood and impact of adverse effects on individuals arising from the processing of personally identifiable information;', true, 2, 5);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ra-3.1_obj', 'ra-3.1', null, null, false, 0, 1);
