insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ra-3.1_obj.b', 'ra-3.1', 'ra-3.1_obj', 'the supply chain risk assessment is updated {{ insert: param, ra-03.01_odp.02 }} , when there are significant changes to the relevant supply chain, or when changes to the system, environments of operation, or other conditions may necessitate a change in the supply chain.', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ra-3.2_obj', 'ra-3.2', null, 'all-source intelligence is used to assist in the analysis of risk.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ra-3.3_obj', 'ra-3.3', null, 'the current cyber threat environment is determined on an ongoing basis using {{ insert: param, ra-03.03_odp }}.', true, 0, 1);
