insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ra-5_obj.b', 'ra-5', 'ra-5_obj', 'vulnerability monitoring tools and techniques are employed to facilitate interoperability among tools;', false, 1, 5);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ra-5_obj.c', 'ra-5', 'ra-5_obj', 'vulnerability scan reports and results from vulnerability monitoring are analyzed;', true, 1, 9);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ra-5_obj.d', 'ra-5', 'ra-5_obj', 'legitimate vulnerabilities are remediated {{ insert: param, ra-05_odp.03 }} in accordance with an organizational assessment of risk;', true, 1, 10);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ra-5_obj.e', 'ra-5', 'ra-5_obj', 'information obtained from the vulnerability monitoring process and control assessments is shared with {{ insert: param, ra-05_odp.04 }} to help eliminate similar vulnerabilities in other systems;', true, 1, 11);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ra-5_obj.f', 'ra-5', 'ra-5_obj', 'vulnerability monitoring tools that include the capability to readily update the vulnerabilities to be scanned are employed.', true, 1, 12);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ra-5_obj.a-1', 'ra-5', 'ra-5_obj.a', 'systems and hosted applications are monitored for vulnerabilities {{ insert: param, ra-05_odp.01 }} and when new vulnerabilities potentially affecting the system are identified and reported;', true, 2, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ra-5_obj.a-2', 'ra-5', 'ra-5_obj.a', 'systems and hosted applications are scanned for vulnerabilities {{ insert: param, ra-05_odp.02 }} and when new vulnerabilities potentially affecting the system are identified and reported;', true, 2, 4);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ra-5_obj.b.1', 'ra-5', 'ra-5_obj.b', 'vulnerability monitoring tools and techniques are employed to automate parts of the vulnerability management process by using standards for enumerating platforms, software flaws, and improper configurations;', true, 2, 6);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ra-5_obj.b.2', 'ra-5', 'ra-5_obj.b', 'vulnerability monitoring tools and techniques are employed to facilitate interoperability among tools and to automate parts of the vulnerability management process by using standards for formatting checklists and test procedures;', true, 2, 7);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ra-5_obj.b.3', 'ra-5', 'ra-5_obj.b', 'vulnerability monitoring tools and techniques are employed to facilitate interoperability among tools and to automate parts of the vulnerability management process by using standards for measuring vulnerability impact;', true, 2, 8);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ra-5.10_obj', 'ra-5.10', null, 'the output from vulnerability scanning tools is correlated to determine the presence of multi-vulnerability and multi-hop attack vectors.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ra-5.11_obj', 'ra-5.11', null, 'a public reporting channel is established for receiving reports of vulnerabilities in organizational systems and system components.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ra-5.2_obj', 'ra-5.2', null, 'the system vulnerabilities to be scanned are updated {{ insert: param, ra-05.02_odp.01 }}.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ra-5.3_obj', 'ra-5.3', null, 'the breadth and depth of vulnerability scanning coverage are defined.', true, 0, 1);
