insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ra-5.4_obj-2', 'ra-5.4', 'ra-5.4_obj', '{{ insert: param, ra-05.04_odp }} are taken when information about the system is confirmed as discoverable.', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ra-5.5_obj', 'ra-5.5', null, 'privileged access authorization is implemented to {{ insert: param, ra-05.05_odp.01 }} for {{ insert: param, ra-05.05_odp.02 }}.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('ra-5.6_obj', 'ra-5.6', null, 'the results of multiple vulnerability scans are compared using {{ insert: param, ra-05.06_odp }}.', true, 0, 1);
