insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('sc-3.2_obj-3', 'sc-3.2', 'sc-3.2_obj', 'security functions enforcing information flow control are isolated from non-security functions;', true, 1, 4);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('sc-3.2_obj-4', 'sc-3.2', 'sc-3.2_obj', 'security functions enforcing information flow control are isolated from other security functions.', true, 1, 5);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('sc-3.3_obj', 'sc-3.3', null, 'the number of non-security functions included within the isolation boundary containing security functions is minimized.', true, 0, 1);
