insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('sc-3.4_obj-2', 'sc-3.4', 'sc-3.4_obj', 'security functions are implemented as largely independent modules that minimize coupling between modules.', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('sc-3.5_obj', 'sc-3.5', null, 'security functions are implemented as a layered structure, minimizing interactions between layers of the design and avoiding any dependence by lower layers on the functionality or correctness of higher layers.', true, 0, 1);
