insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('sc-31.1_obj', 'sc-31.1', null, 'a subset of the identified covert channels is tested to determine the channels that are exploitable.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('sc-31.2_obj', 'sc-31.2', null, 'the maximum bandwidth for identified covert {{ insert: param, sc-31.02_odp.01 }} channels is reduced to {{ insert: param, sc-31.02_odp.02 }}.', true, 0, 1);
