insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('sc-37.1_obj', 'sc-37.1', null, '{{ insert: param, sc-37.01_odp.01 }} are employed to ensure that only {{ insert: param, sc-37.01_odp.02 }} receive {{ insert: param, sc-37.01_odp.03 }}.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('sc-38_obj', 'sc-38', null, '{{ insert: param, sc-38_odp }} are employed to protect key organizational information throughout the system development life cycle.', true, 0, 1);
