insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('sc-4_obj-2', 'sc-4', 'sc-4_obj', 'unintended information transfer via shared system resources is prevented.', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('sc-4.2_obj', 'sc-4.2', null, 'unauthorized information transfer via shared resources is prevented in accordance with {{ insert: param, sc-04.02_odp }} when system processing explicitly switches between different information classification levels or security categories.', true, 0, 1);
