insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('sc-40.1_obj', 'sc-40.1', null, 'cryptographic mechanisms that achieve {{ insert: param, sc-40.01_odp }} against the effects of intentional electromagnetic interference are implemented.', true, 0, 1);
