insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('sc-40.3_obj', 'sc-40.3', null, 'cryptographic mechanisms are implemented to identify and reject wireless transmissions that are deliberate attempts to achieve imitative or manipulative communications deception based on signal parameters.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('sc-40.4_obj', 'sc-40.4', null, 'cryptographic mechanisms are implemented to prevent the identification of {{ insert: param, sc-40.04_odp }} by using the transmitter signal parameters.', true, 0, 1);
