insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('sc-42.2_obj', 'sc-42.2', null, '{{ insert: param, sc-42.02_odp }} are employed so that data or information collected by {{ insert: param, sc-42.01_odp }} is only used for authorized purposes.', true, 0, 1);
