insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('sc-5.1_obj', 'sc-5.1', null, 'the ability of individuals to launch {{ insert: param, sc-05.01_odp }} against other systems is restricted.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('sc-5.2_obj', 'sc-5.2', null, 'capacity, bandwidth, or other redundancies to limit the effects of information flooding denial-of-service attacks are managed.', true, 0, 1);
