insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('sc-7_obj.a-3', 'sc-7', 'sc-7_obj.a', 'communications at key internal managed interfaces within the system are monitored;', true, 2, 5);
