insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('sc-7.15_obj-2', 'sc-7.15', 'sc-7.15_obj', 'networked, privileged accesses are routed through a dedicated, managed interface for purposes of auditing.', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('sc-7.16_obj', 'sc-7.16', null, 'the discovery of specific system components that represent a managed interface is prevented.', true, 0, 1);
