insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('sc-7.18_obj', 'sc-7.18', null, 'systems are prevented from entering unsecure states in the event of an operational failure of a boundary protection device.', true, 0, 1);
