insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('sc-7.19_obj-2', 'sc-7.19', 'sc-7.19_obj', 'outbound communications traffic is blocked between {{ insert: param, sc-07.19_odp }} that are independently configured by end users and external service providers.', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('sc-7.20_obj', 'sc-7.20', null, 'the capability to dynamically isolate {{ insert: param, sc-07.20_odp }} from other system components is provided.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('sc-7.21_obj', 'sc-7.21', null, 'boundary protection mechanisms are employed to isolate {{ insert: param, sc-07.21_odp.01 }} supporting {{ insert: param, sc-07.21_odp.02 }}.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('sc-7.22_obj', 'sc-7.22', null, 'separate network addresses are implemented to connect to systems in different security domains.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('sc-7.23_obj', 'sc-7.23', null, 'feedback to senders is disabled on protocol format validation failure.', true, 0, 1);
