insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('sc-7.24_obj.b-2', 'sc-7.24', 'sc-7.24_obj.b', 'permitted processing is monitored at key internal boundaries within the systems that process personally identifiable information;', true, 2, 5);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('sc-7.24_obj.d-1', 'sc-7.24', 'sc-7.24_obj.d', 'exceptions for systems that process personally identifiable information are reviewed;', true, 2, 8);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('sc-7.24_obj.d-2', 'sc-7.24', 'sc-7.24_obj.d', 'exceptions for systems that process personally identifiable information that are no longer supported are removed.', true, 2, 9);
