insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('sc-7.26_obj', 'sc-7.26', null, 'the direct connection of classified national security system to an external network without the use of a {{ insert: param, sc-07.26_odp }} is prohibited.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('sc-7.27_obj', 'sc-7.27', null, 'the direct connection of {{ insert: param, sc-07.27_odp.01 }} to an external network without the use of a {{ insert: param, sc-07.27_odp.02 }} is prohibited.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('sc-7.28_obj', 'sc-7.28', null, 'the direct connection of the {{ insert: param, sc-07.28_odp }} to a public network is prohibited.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('sc-7.29_obj', 'sc-7.29', null, 'subnetworks are separated {{ insert: param, sc-07.29_odp.01 }} to isolate {{ insert: param, sc-07.29_odp.02 }}.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('sc-7.3_obj', 'sc-7.3', null, 'the number of external network connections to the system is limited.', true, 0, 1);
