insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('si-10.3_obj-2', 'si-10.3', 'si-10.3_obj', 'the system behaves in a documented manner when invalid inputs are received.', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('si-10.4_obj', 'si-10.4', null, 'timing interactions among system components are accounted for in determining appropriate responses for invalid inputs.', true, 0, 1);
