insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('si-18_obj.a-4', 'si-18', 'si-18_obj.a', 'the completeness of personally identifiable information across the information life cycle is checked {{ insert: param, si-18_odp.04 }};', true, 2, 6);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('si-18.1_obj', 'si-18.1', null, '{{ insert: param, si-18.01_odp }} are used to correct or delete personally identifiable information that is inaccurate, outdated, incorrectly determined regarding impact, or incorrectly de-identified.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('si-18.2_obj', 'si-18.2', null, 'data tags are employed to automate the correction or deletion of personally identifiable information across the information life cycle within organizational systems.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('si-18.3_obj', 'si-18.3', null, 'personally identifiable information is collected directly from the individual.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('si-18.4_obj', 'si-18.4', null, 'personally identifiable information is corrected or deleted upon request by individuals or their designated representatives.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('si-18.5_obj', 'si-18.5', null, '{{ insert: param, si-18.05_odp }} and individuals are notified when the personally identifiable information has been corrected or deleted.', true, 0, 1);
