insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('si-19_obj.b', 'si-19', 'si-19_obj', 'the effectiveness of de-identification is evaluated {{ insert: param, si-19_odp.02 }}.', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('si-19.1_obj', 'si-19.1', null, 'the dataset is de-identified upon collection by not collecting personally identifiable information.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('si-19.2_obj', 'si-19.2', null, 'the archiving of personally identifiable information elements is prohibited if those elements in a dataset will not be needed after the dataset is archived.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('si-19.3_obj', 'si-19.3', null, 'personally identifiable information elements are removed from a dataset prior to its release if those elements in the dataset do not need to be part of the data release.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('si-19.4_obj', 'si-19.4', null, 'direct identifiers in a dataset are removed, masked, encrypted, hashed, or replaced.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('si-19.5_obj', 'si-19.5', null, null, false, 0, 1);
