insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('si-19.5_obj-2', 'si-19.5', 'si-19.5_obj', 'contingency tables are manipulated so that no individual or organization is identifiable in the results of the analysis;', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('si-19.5_obj-3', 'si-19.5', 'si-19.5_obj', 'statistical findings are manipulated so that no individual or organization is identifiable in the results of the analysis.', true, 1, 4);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('si-19.6_obj', 'si-19.6', null, 'the disclosure of personally identifiable information is prevented by adding non-deterministic noise to the results of mathematical operations before the results are reported.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('si-19.7_obj', 'si-19.7', null, null, false, 0, 1);
