insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('si-19.7_obj-2', 'si-19.7', 'si-19.7_obj', 'de-identification is performed using software that is validated to implement the algorithms.', true, 1, 3);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('si-19.8_obj', 'si-19.8', null, 'a motivated intruder test is performed on the de-identified dataset to determine if the identified data remains or if the de-identified data can be re-identified.', true, 0, 1);
