insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('si-2_obj.c-2', 'si-2', 'si-2_obj.c', 'security-relevant firmware updates are installed within {{ insert: param, si-02_odp }} of the release of the updates;', true, 2, 13);
