insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('si-3_obj.b', 'si-3', 'si-3_obj', 'malicious code protection mechanisms are updated automatically as new releases are available in accordance with organizational configuration management policy and procedures;', true, 1, 5);
