insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('si-3_obj.c.2-2', 'si-3', 'si-3_obj.c.2', 'malicious code protection mechanisms are configured to send alerts to {{ insert: param, si-03_odp.06 }} in response to malicious code detection;', true, 3, 12);
