insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('si-3.10_obj.b-1', 'si-3.10', 'si-3.10_obj.b', 'the results from malicious code analysis are incorporated into organizational incident response processes;', true, 2, 4);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('si-3.10_obj.b-2', 'si-3.10', 'si-3.10_obj.b', 'the results from malicious code analysis are incorporated into organizational flaw remediation processes.', true, 2, 5);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('si-3.4_obj', 'si-3.4', null, 'malicious code protection mechanisms are updated only when directed by a privileged user.', true, 0, 1);
insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('si-3.6_obj', 'si-3.6', null, null, false, 0, 1);
