insert into control_objective (objective_id, control_id, parent_objective_id, statement, is_leaf, depth, sequence) values ('si-4_obj.a.1', 'si-4', 'si-4_obj.a', 'the system is monitored to detect attacks and indicators of potential attacks in accordance with {{ insert: param, si-04_odp.01 }};', true, 2, 3);
